wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

fn one_line(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn render(digest: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest for ");
    out.push_str(&one_line(&digest.date));
    out.push('\n');

    let overview = digest.overview.trim();
    if !overview.is_empty() {
        out.push('\n');
        out.push_str(overview);
        out.push('\n');
    }

    let mut entries: Vec<&ItemVerdict> = digest.entries.iter().filter(|e| e.kept).collect();
    entries.sort_by_key(|e| importance_rank(e.importance));

    if entries.is_empty() {
        out.push_str("\nNo items made the digest today.\n");
    } else {
        for e in entries {
            out.push('\n');
            out.push_str("- [");
            out.push_str(importance_label(e.importance));
            out.push_str(" / ");
            out.push_str(category_label(e.category));
            out.push_str("] ");
            out.push_str(&one_line(&e.title));
            out.push_str(" (");
            out.push_str(&one_line(&e.feed));
            out.push_str(")\n  ");
            out.push_str(&one_line(&e.link));
            out.push('\n');
            let summary = one_line(&e.summary);
            if !summary.is_empty() {
                out.push_str("  ");
                out.push_str(&summary);
                out.push('\n');
            }
        }
    }

    out.push_str(&format!(
        "\n{} item(s) considered.\n",
        digest.considered.len()
    ));
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let published = notifier::notify(&message);
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

